UPDATE drink_details
SET
deleted_at = NOW() AT TIME ZONE 'Asia/Ho_Chi_Minh',
deleted_by = #{deletedBy}
WHERE drink_id IN (
SELECT drink_id
FROM drinks
WHERE shop_id = #{shopId}
)
AND deleted_at IS NULL

UPDATE profile_shops
